function Invoke-GoogleDnsReq { $domain=$args[0] ; $type=$args[1] ; Invoke-RestMethod -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36' -Uri "https://dns.google/resolve?name=$domain&rtype=$type" }                  
function Invoke-CfDnsReq { $domain=$args[0] ; $type=$args[1] ; Invoke-RestMethod -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36' -Headers @{"Accept"="application/dns-json"} -Uri "https://one.one.one.one/dns-query?name=$domain&rtype=$type" }
function Invoke-AzMap { $domain=$args[0] ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://azmap.dev/api/tenant?domain=$domain" }
function Get-AzTenantDomainOIDC { $domain=$args[0] ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://login.microsoftonline.com/$domain/v2.0/.well-known/openid-configuration" }
# function Invoke-AzExternalTenantDomains { $domain=$args[0] ; $tenant=$(Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://azmap.dev/api/tenant?domain=$domain" | Select-Object -ExpandProperty tenant_id) ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://tenant-api.micahvandeusen.com/search?tenant_id=$tenant" | Select-Object -ExpandProperty domains ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://azmap.dev/api/tenant?domain=$domain" | Select-Object -ExpandProperty related_domains }
